macro.sample.deck:
var n = deck.AddSlide();
deck.SetTitle(n, "Zusammenfassung");
deck.SetBody(n, "Folien: " + deck.SlideCount);
app.Log(deck.Title(n));

macro.sample.folio:
var n = doc.AppendParagraph("Zusammenfassung");
doc.SetStyle(n, "Heading 1");
doc.AppendParagraph("Wörter: " + doc.WordCount);
app.Log(doc.Paragraph(n));
